129	/****************************************************************************
130	 * Name: spi_write_byte
131	 ****************************************************************************/
132	
133	static void spi_write_byte(uint8_t byte)
134	{
135	  int bit;
136	
137	  for (bit = 7; bit >= 0; bit--)
138	    {
139	      gpio_write(LCD_PIN_MOSI, (byte >> bit) & 1);
140	      spi_delay();
141	      gpio_write(LCD_PIN_SCLK, 1);
142	      spi_delay();
143	      gpio_write(LCD_PIN_SCLK, 0);
144	    }
145	}
