451	/****************************************************************************
452	 * Name: lcdtest_pwr
453	 *
454	 * Description:
455	 *   Full power-on sequence with configurable GPIO range for binary-search
456	 *   identification of the LCD power enable pin.
457	 *
458	 *   Usage: lcdtest pwr [lo] [hi]
459	 *     lo..hi  — decimal GPIO range to drive high (default 0..52)
460	 *
461	 *   Always skips: 2,3,4,5,25,29 (LCD)  10,11 (UART)  7,8 (motor)
462	 *                 20,21 (SWD)  38,39 (LEDs)
463	 *
464	 ****************************************************************************/
465	
466	static int lcdtest_pwr(int lo, int hi)
467	{
468	  int pin;
469	  int count = 0;
470	  int off = 0;
471	  char pinbuf[256];
472	
473	  /* Step 1: drive GPIO lo..hi high, skip reserved pins.
474	   * Collect the actual pin list for the syslog dump.
475	   */
476	
477	  syslog(LOG_INFO,
478	         "[pwr] step1: GPIO %d-%d high (skip reserved)\n",
479	         lo, hi);
480	
481	  for (pin = lo; pin <= hi; pin++)
482	    {
483	      /* LCD signals */
484	
485	      if (pin == 2 || pin == 3 || pin == 4 || pin == 5 ||
486	          pin == 25 || pin == 29)
487	        {
488	          continue;
489	        }
490	
491	      /* UART0 console */
492	
493	      if (pin == 10 || pin == 11)
494	        {
495	          continue;
496	        }
497	
498	      /* Vibration motor */
499	
500	      if (pin == 7 || pin == 8)
501	        {
502	          continue;
503	        }
504	
505	      /* Indicator LEDs */
506	
507	      if (pin == 38 || pin == 39)
508	        {
509	          continue;
510	        }
511	
512	      /* SWD debug port: SWCLK=20, SWDIO=21 */
513	
514	      if (pin == 20 || pin == 21)
515	        {
516	          continue;
517	        }
518	
519	      gpio_set_output(pin);
520	      gpio_write(pin, 1);
521	      count++;
522	
523	      if (off < (int)sizeof(pinbuf) - 8)
524	        {
525	          off += snprintf(pinbuf + off, sizeof(pinbuf) - off,
526	                          " %d", pin);
527	        }
528	    }
529	
530	  pinbuf[off] = '\0';
531	
532	  /* Print which pins were actually driven high */
533	
534	  syslog(LOG_INFO,
535	         "[pwr] driven high (%d pins):%s\n", count, pinbuf);
536	
537	  /* Step 2: wait for power rails to settle */
538	
539	  syslog(LOG_INFO, "[pwr] step2: wait 50 ms ...\n");
540	  up_mdelay(50);
541	
542	  /* Step 3: backlight on */
543	
544	  syslog(LOG_INFO, "[pwr] step3: backlight P25 high\n");
545	  gpio_set_output(LCD_PIN_BL);
546	  gpio_write(LCD_PIN_BL, 1);
547	
548	  /* Step 4: hardware reset */
549	
550	  syslog(LOG_INFO,
551	         "[pwr] step4: RST(P29) low 15 ms then high\n");
552	  gpio_set_output(LCD_PIN_RST);
553	  gpio_write(LCD_PIN_RST, 0);
554	  up_mdelay(15);
555	  gpio_write(LCD_PIN_RST, 1);
556	  up_mdelay(120);
557	
558	  /* Step 5: GC9D01 init sequence */
559	
560	  syslog(LOG_INFO, "[pwr] step5: GC9D01 init sequence\n");
561	  lcd_init_sequence();
562	
563	  /* Step 6: clear screen to black */
564	
565	  syslog(LOG_INFO, "[pwr] step6: fill screen black\n");
566	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, 0x0000);
567	
568	  /* Step 7: draw 40x40 red square at (60,60) */
569	
570	  syslog(LOG_INFO,
571	         "[pwr] step7: fill 40x40 red at (60,60)\n");
572	  lcd_fill_rect(60, 60,
573	                60 + SQ_SIZE - 1, 60 + SQ_SIZE - 1,
574	                0xf800);
575	
576	  syslog(LOG_INFO,
577	         "[pwr] done (%d pins driven) - "
578	         "screen should show red on black\n",
579	         count);
580	  return OK;
581	}
