583	/****************************************************************************
584	 * Name: lcdtest_go
585	 *
586	 * Description:
587	 *   One-step reliable LCD bring-up.  Drives all GPIO power/enable pins
588	 *   high, waits for supply stabilisation, then initialises the GC9D01
589	 *   and draws the test pattern.  This is the production-ready flow
590	 *   confirmed through binary-search pin identification.
591	 *
592	 ****************************************************************************/
593	
594	static int lcdtest_go(void)
595	{
596	  int pin;
597	  int count = 0;
598	
599	  /* Step 1: drive GPIO 0-52 high, skip reserved pins */
600	
601	  syslog(LOG_INFO,
602	         "[go] step1: GPIO 0-52 high (skip reserved)\n");
603	
604	  for (pin = 0; pin <= 52; pin++)
605	    {
606	      /* LCD signals */
607	
608	      if (pin == 2 || pin == 3 || pin == 4 || pin == 5 ||
609	          pin == 25 || pin == 29)
610	        {
611	          continue;
612	        }
613	
614	      /* UART0 console */
615	
616	      if (pin == 10 || pin == 11)
617	        {
618	          continue;
619	        }
620	
621	      /* Vibration motor */
622	
623	      if (pin == 7 || pin == 8)
624	        {
625	          continue;
626	        }
627	
628	      /* Indicator LEDs */
629	
630	      if (pin == 38 || pin == 39)
631	        {
632	          continue;
633	        }
634	
635	      /* SWD debug port: SWCLK=20, SWDIO=21 */
636	
637	      if (pin == 20 || pin == 21)
638	        {
639	          continue;
640	        }
641	
642	      gpio_set_output(pin);
643	      gpio_write(pin, 1);
644	      count++;
645	    }
646	
647	  syslog(LOG_INFO, "[go] step1 done: %d pins driven high\n", count);
648	
649	  /* Step 2: wait for power rails to settle */
650	
651	  syslog(LOG_INFO, "[go] step2: wait 500 ms for power stable\n");
652	  up_mdelay(500);
653	
654	  /* Step 3: backlight on */
655	
656	  syslog(LOG_INFO, "[go] step3: backlight P25 high\n");
657	  gpio_set_output(LCD_PIN_BL);
658	  gpio_write(LCD_PIN_BL, 1);
659	
660	  /* Step 3b: configure SPI pins as output, set idle levels */
661	
662	  syslog(LOG_INFO,
663	         "[go] step3b: SPI pins SCLK/CS/MOSI/DC output + idle\n");
664	  gpio_set_output(LCD_PIN_SCLK);
665	  gpio_set_output(LCD_PIN_CS);
666	  gpio_set_output(LCD_PIN_MOSI);
667	  gpio_set_output(LCD_PIN_DC);
668	  gpio_set_output(LCD_PIN_RST);
669	
670	  gpio_write(LCD_PIN_CS, 1);
671	  gpio_write(LCD_PIN_DC, 1);
672	  gpio_write(LCD_PIN_SCLK, 0);
673	  gpio_write(LCD_PIN_MOSI, 0);
674	
675	  /* Step 4: first RST + init */
676	
677	  gpio_set_output(LCD_PIN_RST);
678	
679	  syslog(LOG_INFO,
680	         "[go] step4: RST+init pass 1\n");
681	  gpio_write(LCD_PIN_RST, 0);
682	  up_mdelay(15);
683	  gpio_write(LCD_PIN_RST, 1);
684	  up_mdelay(120);
685	  lcd_init_sequence();
686	
687	  /* Step 5: fill screen black — the slow bit-bang provides the
688	   * multi-second delay that VCI POR needs before pass 2 works.
689	   */
690	
691	  syslog(LOG_INFO, "[go] step5: fill screen black (delays ~2s)\n");
692	  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, 0x0000);
693	
694	  /* Step 6: second RST + init (POR now settled) */
695	
696	  syslog(LOG_INFO, "[go] step6: RST+init pass 2\n");
697	  gpio_write(LCD_PIN_RST, 0);
698	  up_mdelay(15);
699	  gpio_write(LCD_PIN_RST, 1);
700	  up_mdelay(120);
701	  lcd_init_sequence();
702	
703	  /* Step 7: draw 40x40 red square at (60,60) */
704	
705	  syslog(LOG_INFO,
706	         "[go] step7: fill 40x40 red at (60,60)\n");
707	  lcd_fill_rect(60, 60,
708	                60 + SQ_SIZE - 1, 60 + SQ_SIZE - 1,
709	                0xf800);
710	
711	  syslog(LOG_INFO,
712	         "[go] done - screen should show red on black\n");
