720	/****************************************************************************
721	 * Name: bk7258_lcdtest_main
722	 *
723	 * Description:
724	 *   NSH command "lcdtest":
725	 *     lcdtest          — staged bring-up (A/B/C, diagnostics)
726	 *     lcdtest go       — one-step reliable LCD bring-up
727	 *     lcdtest pwr lo hi — power-on GPIO range for binary-search
728	 *     lcdtest scan     — GPIO pin scan for LCD power enable
729	 *
730	 ****************************************************************************/
731	
732	int bk7258_lcdtest_main(int argc, char *argv[])
733	{
734	  if (argc > 1 && strcmp(argv[1], "go") == 0)
735	    {
736	      return lcdtest_go();
737	    }
738	
739	  if (argc > 1 && strcmp(argv[1], "scan") == 0)
740	    {
741	      return lcdtest_scan();
742	    }
743	
744	  if (argc > 1 && strcmp(argv[1], "pwr") == 0)
745	    {
746	      int lo = 0;
747	      int hi = 52;
748	
749	      if (argc > 2)
750	        {
751	          lo = atoi(argv[2]);
752	        }
753	
754	      if (argc > 3)
755	        {
756	          hi = atoi(argv[3]);
757	        }
758	
759	      if (lo < 0)
760	        {
761	          lo = 0;
762	        }
763	
764	      if (hi > 52)
765	        {
766	          hi = 52;
767	        }
768	
769	      if (lo > hi)
770	        {
771	          syslog(LOG_ERR,
772	                 "[pwr] error: lo(%d) > hi(%d)\n", lo, hi);
773	          return -EINVAL;
774	        }
775	
776	      return lcdtest_pwr(lo, hi);
777	    }
778	
779	  return lcdtest_stages();
780	}
