93	 * Private Functions
94	 ****************************************************************************/
95	
96	/****************************************************************************
97	 * Name: gpio_set_output
98	 ****************************************************************************/
99	
100	static void gpio_set_output(int pin)
101	{
102	  uint32_t cfg = getreg32(BK7258_GPIO_CFG(pin));
103	
104	  cfg &= ~GPIO_CFG_SECOND_FUNC;  /* GPIO mode (bit6 = 0) */
105	  cfg &= ~GPIO_CFG_OUTPUT_EN;    /* output enable (bit3 active-low: 0 = on) */
106	  cfg &= ~GPIO_CFG_INPUT_EN;     /* input disable (bit2 active-high: 0 = off) */
107	  putreg32(cfg, BK7258_GPIO_CFG(pin));
108	}
109	
110	/****************************************************************************
111	 * Name: gpio_write
112	 ****************************************************************************/
113	
114	static void gpio_write(int pin, int val)
115	{
116	  uint32_t cfg = getreg32(BK7258_GPIO_CFG(pin));
117	
118	  if (val)
119	    {
120	      cfg |= GPIO_CFG_OUTPUT;
121	    }
122	  else
123	    {
124	      cfg &= ~GPIO_CFG_OUTPUT;
125	    }
126	
127	  putreg32(cfg, BK7258_GPIO_CFG(pin));
128	}
