130	/****************************************************************************
131	 * Name: spi_write_byte
132	 ****************************************************************************/
133	
134	static void spi_write_byte(uint8_t byte)
135	{
136	  int bit;
137	
138	  for (bit = 7; bit >= 0; bit--)
139	    {
140	      gpio_write(LCD_PIN_MOSI, (byte >> bit) & 1);
141	      spi_delay();
142	      gpio_write(LCD_PIN_SCLK, 1);
143	      spi_delay();
144	      gpio_write(LCD_PIN_SCLK, 0);
145	    }
146	}
