286	/****************************************************************************
287	 * Name: lcd_fill_rect
288	 *
289	 * Description:
290	 *   Fill a rectangle (x0,y0)-(x1,y1) with a single RGB565 color.
291	 *   Much smaller than full-screen fill — avoids millions of bit-bangs.
292	 *
293	 ****************************************************************************/
294	
295	static void lcd_fill_rect(uint16_t x0, uint16_t y0,
296	                          uint16_t x1, uint16_t y1,
297	                          uint16_t color)
298	{
299	  uint8_t ca[4];
300	  uint8_t ra[4];
301	  uint8_t hi = (color >> 8) & 0xff;
302	  uint8_t lo = color & 0xff;
303	  int npix = (int)(x1 - x0 + 1) * (int)(y1 - y0 + 1);
304	  int i;
305	
306	  /* CASET */
307	
308	  ca[0] = (x0 >> 8) & 0xff;
309	  ca[1] = x0 & 0xff;
310	  ca[2] = (x1 >> 8) & 0xff;
311	  ca[3] = x1 & 0xff;
312	  lcd_send_cmd_data(0x2a, ca, 4);
313	
314	  /* RASET */
315	
316	  ra[0] = (y0 >> 8) & 0xff;
317	  ra[1] = y0 & 0xff;
318	  ra[2] = (y1 >> 8) & 0xff;
319	  ra[3] = y1 & 0xff;
320	  lcd_send_cmd_data(0x2b, ra, 4);
321	
322	  /* RAMWR + pixel data */
323	
324	  lcd_send_cmd(0x2c);
325	  gpio_write(LCD_PIN_DC, 1);
326	  gpio_write(LCD_PIN_CS, 0);
327	  for (i = 0; i < npix; i++)
328	    {
329	      spi_write_byte(hi);
330	      spi_write_byte(lo);
331	    }
332	
333	  gpio_write(LCD_PIN_CS, 1);
334	}
