390	  syslog(LOG_INFO,
391	         "[lcdtest] Stage C: fill 40x40 red at (60,60)\n");
392	
393	  lcd_fill_rect(60, 60,
394	                60 + SQ_SIZE - 1, 60 + SQ_SIZE - 1,
