604	/****************************************************************************
605	 * Name: lcdtest_go
606	 *
607	 * Description:
608	 *   One-step reliable LCD bring-up.  Drives all GPIO power/enable pins
609	 *   high, waits for supply stabilisation, then initialises the GC9D01
610	 *   and draws the test pattern.  This is the production-ready flow
611	 *   confirmed through binary-search pin identification.
612	 *
613	 ****************************************************************************/
614	
615	static int lcdtest_go(void)
616	{
617	  int pin;
618	  int count = 0;
619	
620	  /* Step 1: drive GPIO 0-52 high, skip reserved pins */
621	
622	  syslog(LOG_INFO,
623	         "[go] step1: GPIO 0-52 high (skip reserved)\n");
624	
625	  for (pin = 0; pin <= 52; pin++)
626	    {
627	      /* LCD signals */
628	
629	      if (pin == 2 || pin == 3 || pin == 4 || pin == 5 ||
630	          pin == 25 || pin == 29)
631	        {
632	          continue;
633	        }
634	
635	      /* UART0 console */
636	
637	      if (pin == 10 || pin == 11)
638	        {
639	          continue;
640	        }
641	
642	      /* Vibration motor */
643	
644	      if (pin == 7 || pin == 8)
645	        {
646	          continue;
647	        }
648	
649	      /* Indicator LEDs */
650	
651	      if (pin == 38 || pin == 39)
652	        {
653	          continue;
654	        }
655	
656	      /* SWD debug port: SWCLK=20, SWDIO=21 */
657	
658	      if (pin == 20 || pin == 21)
659	        {
660	          continue;
661	        }
662	
663	      gpio_set_output(pin);
664	      gpio_write(pin, 1);
665	      count++;
666	    }
667	
668	  syslog(LOG_INFO, "[go] step1 done: %d pins driven high\n", count);
669	
670	  /* Step 2: wait for power rails to settle */
671	
672	  syslog(LOG_INFO, "[go] step2: wait 500 ms for power stable\n");
673	  up_mdelay(500);
674	
675	  /* Step 3: backlight on */
676	
677	  syslog(LOG_INFO, "[go] step3: backlight P25 high\n");
678	  gpio_set_output(LCD_PIN_BL);
679	  gpio_write(LCD_PIN_BL, 1);
680	
681	  /* Step 3b: configure SPI pins as output, set idle levels */
682	
683	  syslog(LOG_INFO,
684	         "[go] step3b: SPI pins SCLK/CS/MOSI/DC output + idle\n");
685	  gpio_set_output(LCD_PIN_SCLK);
686	  gpio_set_output(LCD_PIN_CS);
687	  gpio_set_output(LCD_PIN_MOSI);
688	  gpio_set_output(LCD_PIN_DC);
689	  gpio_set_output(LCD_PIN_RST);
690	
691	  gpio_write(LCD_PIN_CS, 1);
692	  gpio_write(LCD_PIN_DC, 1);
693	  gpio_write(LCD_PIN_SCLK, 0);
694	  gpio_write(LCD_PIN_MOSI, 0);
695	
696	  /* Step 4: RST + init (display OFF — avoids flash of garbage GRAM) */
697	
698	  syslog(LOG_INFO, "[go] step4: RST + init (display off)\n");
699	  gpio_write(LCD_PIN_RST, 0);
700	  up_mdelay(15);
